#!/usr/bin/env bash
# Writes deploy/staging/.env for the beluno.site host with fresh secrets, generated here and
# never printed. Refuses to overwrite an existing file: secrets in use stay as they are.
#   bash deploy/vps/make-env.sh   (on the host, from the repository root)
set -euo pipefail
cd "$(dirname "$0")/../staging"
if [ -e .env ]; then
  echo ".env already exists; nothing written" >&2
  exit 0
fi
umask 077
secret() { openssl rand -hex 24; }
cat > .env <<EOF
# beluno.site staging. Generated by deploy/vps/make-env.sh; secrets never leave this host.
POSTGRES_DB=beluno
POSTGRES_PASSWORD=$(secret)
BELUNO_MIGRATOR_DB_PASSWORD=$(secret)
BELUNO_API_DB_PASSWORD=$(secret)
BELUNO_WORKER_DB_PASSWORD=$(secret)
BELUNO_SCHEDULER_DB_PASSWORD=$(secret)

BELUNO_AUTH_ISSUER=beluno
BELUNO_AUTH_AUDIENCE=beluno-api
BELUNO_AUTH_GOOGLE_CLIENT_IDS=[]
BELUNO_AUTH_APPLE_CLIENT_IDS=[]
BELUNO_AUTH_MAGIC_LINK_URL=https://beluno.site/auth/email
# Passkeys: the site and the app signed with the debug and upload keys (add the Play signing key
# once Play Console shows it).
BELUNO_WEBAUTHN_RP_ID=beluno.site
BELUNO_WEBAUTHN_ORIGINS='["https://beluno.site","android:apk-key-hash:NTorDXUTiolCyfYtHioFQliPT6feqJmFnyNcmoDXNDA","android:apk-key-hash:RoBJFNUalOx54jAaFgO6Jt-bgAHnQLr3iiwiTWcoVdY"]'

BELUNO_STORAGE_ACCESS_KEY_ID=beluno
BELUNO_STORAGE_SECRET_ACCESS_KEY=$(secret)
BELUNO_STORAGE_PUBLIC_URL=https://files.beluno.site
RUSTFS_VERSION=1.0.1
CLAMAV_VERSION=1.4

# The bundled PostgreSQL speaks plain text on the internal network (see env.example).
BELUNO_ENVIRONMENT=development
BELUNO_LOG_LEVEL=INFO
BELUNO_RELEASE=staging
# Ports 80/443 belong to the shared Caddy on aloudo_default (gateway 172.22.0.1). The API and RustFS
# publish only on that gateway address, so Caddy reaches them without Beluno joining the shared
# network (where its service names would clash with other apps' api/postgres).
BELUNO_PUBLISH_ADDRESS=172.22.0.1
BELUNO_API_PORT=8100
BELUNO_STORAGE_PUBLISH_ADDRESS=172.22.0.1
BELUNO_STORAGE_PORT=9100
FORWARDED_ALLOW_IPS=172.16.0.0/12

# Console until Resend is set up (codes print in the worker log).
BELUNO_EMAIL_BACKEND=console
BELUNO_EMAIL_FROM=Beluno <no-reply@beluno.site>
BELUNO_SMTP_HOST=smtp.resend.com
BELUNO_SMTP_PORT=587
BELUNO_SMTP_USERNAME=resend
BELUNO_SMTP_SECURITY=starttls

# Not started on this host, but compose requires the value.
GRAFANA_ADMIN_PASSWORD=$(secret)
EOF
echo ".env written. Add the identity keys from a development checkout (the runtime image lacks the dev tools):"
echo "  uv run python scripts/generate_signing_key.py --with-token-hash-key --with-booking-keys | ssh root@<host> 'cat >> /opt/beluno/backend/deploy/staging/.env'"
